do $body$ begin if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls; end if; end $body$;
create schema auth;
create table auth.users(id uuid primary key default gen_random_uuid());
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
grant usage on schema auth to anon, authenticated, service_role;
grant usage on schema public to anon, authenticated, service_role;
create type user_role as enum('user','babalawo','admin');
create table public.profiles(id uuid primary key, role user_role default 'user');
create function public.is_admin() returns boolean language sql security definer stable as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create table public.admin_settings(id uuid primary key default gen_random_uuid(), setting_key text unique, setting_value text, description text);
create type session_status_enum as enum('pending','confirmed','completed','cancelled','in_progress');
create table public.babalawos(id bigserial primary key, user_id uuid unique references auth.users, hourly_rate numeric default 0, is_active boolean default true,
  commission_platform_percent numeric default 20, commission_babalawo_percent numeric default 80, updated_at timestamptz default now());
create table public.sessions(id bigserial primary key, user_id uuid, babalawo_id uuid, session_date date, start_time time, end_time time,
  status session_status_enum default 'pending', payment_status text default 'pending', amount numeric, payment_reference text, notes text,
  is_instant boolean, user_timezone text, idempotency_key text unique, created_at timestamptz default now());
alter table public.sessions enable row level security;
create policy s_all on public.sessions for all using (true) with check (true);
grant all on public.sessions to authenticated;
create table public.wallets(id uuid primary key default gen_random_uuid(), user_id uuid unique, balance numeric(10,2) not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
alter table public.wallets enable row level security;
create policy "Users can update their own wallet" on public.wallets for update using (auth.uid()=user_id);
create policy "Users can view their own wallet" on public.wallets for select using (auth.uid()=user_id);
grant all on public.wallets to authenticated;
create table public.wallet_transactions(id uuid primary key default gen_random_uuid(), user_id uuid, wallet_id uuid, amount numeric, transaction_type text, transaction_source text check (transaction_source in ('payment_gateway','session_payment','refund','admin_adjustment')), payment_gateway text, payment_reference text, session_id uuid, description text, created_at timestamptz default now());
alter table public.wallet_transactions enable row level security;
grant all on public.wallet_transactions to authenticated;
create table public.payments(id uuid primary key default gen_random_uuid(), user_id uuid, session_id bigint, amount numeric, commission_amount numeric default 0, babalawo_amount numeric default 0, payment_gateway text, payment_reference text, status text, webhook_verified boolean, created_at timestamptz default now(), updated_at timestamptz default now());
alter table public.payments enable row level security; grant all on public.payments to authenticated;
create table public.refunds(id uuid primary key default gen_random_uuid(), payment_id uuid, amount numeric, reason text, status text, processed_by uuid, created_at timestamptz default now());
create table public.babalawo_wallets(id uuid primary key default gen_random_uuid(), babalawo_id uuid references auth.users, available_balance numeric(12,2) default 0 not null, updated_at timestamptz default now());
alter table public.babalawo_wallets enable row level security; grant all on public.babalawo_wallets to authenticated;
create policy "Babalawos can update their own wallet" on public.babalawo_wallets for update using (auth.uid()=babalawo_id);
create policy bw_sel on public.babalawo_wallets for select using (auth.uid()=babalawo_id);
create table public.withdrawal_requests(id uuid primary key default gen_random_uuid(), babalawo_id uuid, amount numeric, status text default 'pending', created_at timestamptz default now(), updated_at timestamptz default now());
alter table public.withdrawal_requests enable row level security; grant all on public.withdrawal_requests to authenticated;
create table public.payouts(id uuid primary key default gen_random_uuid(), babalawo_id uuid, amount numeric, method text, reference text, status text, created_at timestamptz default now());
alter table public.payouts enable row level security; grant all on public.payouts to authenticated;
create table public.babalawo_bank_details(id uuid primary key default gen_random_uuid(), babalawo_id uuid, account_name text, account_number text, bank_name text, updated_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid, type text, title text, message text, data jsonb, priority text);
create table public.payment_audit_log(id uuid primary key default gen_random_uuid(), payment_id uuid, event_type text, event_data jsonb, ip_address inet, user_agent text);
create function public.create_notification(p_user_id uuid,p_type text,p_title text,p_message text,p_data jsonb default null,p_priority text default 'normal') returns uuid language sql security definer as $$ insert into notifications(user_id,type,title,message,data,priority) values(p_user_id,p_type,p_title,p_message,p_data,p_priority) returning id $$;
create function public.log_payment_audit(p_payment_id uuid,p_event_type text,p_event_data jsonb default null,p_ip_address inet default null,p_user_agent text default null) returns uuid language sql security definer as $$ insert into payment_audit_log(payment_id,event_type,event_data) values(p_payment_id,p_event_type,p_event_data) returning id $$;
create function public.update_wallet_balance(p_user_id uuid,p_amount numeric,p_transaction_type text,p_transaction_source text) returns uuid language sql as $$ select null::uuid $$;
grant execute on all functions in schema public to anon, authenticated;
